"text": "Inhoudsopgave\n1.\nVoor je een inrichting opstart\n5\n2.\nHoe verloopt een controle van het FAVV?\n9\n2.1.\nAdministratieve controle\n9\n2.2.\nFysieke controle\n9\n2.3.\nMogelijke maatregelen\n10\n3.\nHoe bereid je je voor op een controle\n13\n4.\nMeer praktische informatie\n17\n4.1.\nKoudeketen: temperatuur\n17\n4.2.\nWat betekenen de data op de verpakkingen?\n20\n4.3.\nAllergenen\n22\n4.4.\nDe controles bij ontvangst van de goederen\n25\n5.\nWaarvoor je verantwoordelijk bent\n27\n5.1.\nAutocontrole\n27\n5.2.\nTraceerbaarheid\n31\n5.3.\nMeldingsplicht\n34\n6.\nCertificering van de autocontrole: de smiley\n36\n7.\nPublicatie van de inspectieresultaten\n37\nBijlage : Lijst van de LCE’s & voorlichtingcel\n38\nVerantwoordelijke uitgever: Herman Diricks\nKruidtuinlaan 55 - 1000 Brussel - November 2018\nDépôt légal : D/2011/10413/8\n3"
