"text": "DETAILHANDEL\nHORECA\nGROOTKEUKEN\nKINDERDAGVERBLIJF\nSLAGERIJ\nBAKKERIJ\nHOEVEVERKOOP\nAMBULANTE HANDEL\nFRITUUR\n...\n4"
