"text": "Gelet op de wet van 21 juni 1983 betreffende gemedicineerd\ndiervoeders, gewijzigd bij de koninklijke besluiten van 7 maart 1995 en\n22 februari 2001, en bij de wet van 28 maart 2003;\nGelet op de wet van 14 augustus 1986 betreffende de bescherming en\nhet welzijn der dieren gewijzigd bij de wetten van 28 augustus 1991,\n26 maart 1993, 4 mei 1995, 19 juli 2001 en 22 december 2003, en bij het\nkoninklijk besluit van 22 februari 2001;\nGelet op de dierengezondheidswet van 24 maart 1987, gewijzigd bij\nde wetten van 29 december 1990, 20 juli 1991, 6 augustus 1993,\n21 december 1994, 20 december 1995, 23 maart 1998 en 5 februari 1999,\nen bij het koninklijk besluit van 22 februari 2001;\nGelet op de wet van 21 december 1998 betreffende de productnormen\nter bevordering van duurzame productie- en consumptiepatronen en\nter bescherming van het leefmilieu en de volksgezondheid, gewijzigd\nbij de wetten van 4 april 2001, 28 maart 2003, 22 december 2003,\n9 juli 2004, 27 december 2004 en 20 juli 2005;\nGelet op de wet van 4 februari 2000 houdende oprichting van het\nFederaal Agentschap voor de Veiligheid van de Voedselketen, inzon-\nderheid op artikel 5;\nGelet op het koninklijk besluit van 22 februari 2001 houdende\norganisatie van de controles die worden verricht door het Federaal\nAgentschap voor de Veiligheid van de Voedselketen en tot wijziging"
