"text": "Art. 80. In artikel 45 van hetzelfde besluit worden volgende wijzi-\ngingen aangebracht : ti\n1° in de eerste alinea worden de woorden « de Minister » vervangen\ndoor de woorden « het Agentschap », wordt het woord « vergunning »\nvervangen door het woord « toelating » en vervallen de woorden « de\nregistratie »;\n2° in de eerste zin van de eerste alinea wordt tussen de woorden\n« weigeren » en « of » het woord « schorsen » ingevoegd;\n3° de derde zin van de eerste alinea vervalt;\n4° in de tweede alinea worden de woorden « de Minister » vervangen\ndoor de woorden « het Agentschap »; «\n5° in de tweede alinea wordt tussen het woord « schorsen » en het\nwoord « of » het woord « weigeren » ingevoegd. «"
